def f_std_parity(x, y):
    # Calculate T_{x+y} = (x+y)(x+y+1)/2 mod 2
    S = x + y
    T_S = (S * (S + 1) // 2) % 2

    # f_std(x, y) = T_S + x mod 2
    return (T_S + (x % 2)) % 2

M = 100
odd_count = 0
for x in range(M):
    for y in range(M):
        if f_std_parity(x, y) == 1:
            odd_count += 1

print(f"N for M=100 using f_std: {odd_count}")

def f_standard(x, y):
    # Standard canonical bijection used in notes
    return (x + y) * (x + y + 1) // 2 + y

N = 0
grid_size = 100

for x in range(grid_size):
    for y in range(grid_size):
        value = f_standard(x, y)
        if value % 2 != 0:
            N += 1

print(f"Count N for f_standard on 100x100 grid: {N}")

def f_standard(x, y):
    # Diagonal enumeration method
    return (x + y) * (x + y + 1) // 2 + y

def f_alt(x, y):
    # Alternative canonical method using min(x, y)
    return (x + y) * (x + y + 1) // 2 + min(x, y)

grid_size = 100
count_std = 0
count_alt = 0

for x in range(grid_size):
    for y in range(grid_size):
        # Check standard function
        if f_standard(x, y) % 2 != 0:
            count_std += 1

        # Check alternative function
        if f_alt(x, y) % 2 != 0:
            count_alt += 1

print(f"Count N for f_standard (Diagonal + y): {count_std}")
print(f"Count N for f_alt (Diagonal + min(x,y)): {count_alt}")

